package android.util;
public class Log {public static int d(String t,String s){if(Boolean.getBoolean("hecker.test.logs"))System.err.println(t+": "+s);return 0;} public static int d(String t,String s,Throwable e){if(Boolean.getBoolean("hecker.test.logs")){System.err.println(t+": "+s);e.printStackTrace();}return 0;}public static int i(String t,String s){if(Boolean.getBoolean("hecker.test.logs"))System.err.println(t+": "+s);return 0;} public static int i(String t,String s,Throwable e){if(Boolean.getBoolean("hecker.test.logs")){System.err.println(t+": "+s);e.printStackTrace();}return 0;}public static int w(String t,String s){if(Boolean.getBoolean("hecker.test.logs"))System.err.println(t+": "+s);return 0;} public static int w(String t,String s,Throwable e){if(Boolean.getBoolean("hecker.test.logs")){System.err.println(t+": "+s);e.printStackTrace();}return 0;}public static int e(String t,String s){if(Boolean.getBoolean("hecker.test.logs"))System.err.println(t+": "+s);return 0;} public static int e(String t,String s,Throwable e){if(Boolean.getBoolean("hecker.test.logs")){System.err.println(t+": "+s);e.printStackTrace();}return 0;}}
